local EggCupMaker = {}
local PRODUCTS = {
    iron_eggcup = { name = "Železni skodelica za jajca", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni skodelica za jajca za kuharje." },
    bronze_eggcup = { name = "Bronast skodelica za jajca", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast skodelica za jajca za kuharje." },
    silver_eggcup = { name = "Srebrn skodelica za jajca", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn skodelica za jajca za kuharje." },
    gilded_eggcup = { name = "Pozlačen skodelica za jajca", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen skodelica za jajca za kuharje." },
    jewel_set_eggcup = { name = "Draguljast skodelica za jajca", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast skodelica za jajca za kuharje." },
    royal_sovereign_eggcup = { name = "Kraljevski suveren skodelica za jajca", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren skodelica za jajca z biseri za krono." },
}
local BUILDINGS = {
    eggcup_workshop = { name = "Eggcup delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    eggcup_house = { name = "Eggcup hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_eggcup_atelier = { name = "Mojstrski eggcup atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_eggcup_palace = { name = "Suverena eggcup palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
EggCupMaker.ironStock=12; EggCupMaker.bronzeStock=10; EggCupMaker.woodStock=14; EggCupMaker.leatherStock=8; EggCupMaker.silverStock=8; EggCupMaker.goldStock=6; EggCupMaker.jewelStock=4; EggCupMaker.pearlStock=4
EggCupMaker.productStock = {}; EggCupMaker.buildings = {}; EggCupMaker.maker = nil; EggCupMaker.activeMaking = {}; EggCupMaker.totalProducts = 0; EggCupMaker.dayTimer = 0
function EggCupMaker.init() EggCupMaker.ironStock=12; EggCupMaker.bronzeStock=10; EggCupMaker.woodStock=14; EggCupMaker.leatherStock=8; EggCupMaker.silverStock=8; EggCupMaker.goldStock=6; EggCupMaker.jewelStock=4; EggCupMaker.pearlStock=4; EggCupMaker.productStock={}; EggCupMaker.buildings={}; EggCupMaker.maker=nil; EggCupMaker.activeMaking={}; EggCupMaker.totalProducts=0; EggCupMaker.dayTimer=0; print("[EggCupMaker] Royal Egg Cup Maker System initialized (6 products, 4 buildings)") end
function EggCupMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; EggCupMaker.maker={name=n or ("Skodeličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skodeličar najet: %s (spretnost: %d)",EggCupMaker.maker.name,s),"success") end; return true end
function EggCupMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function EggCupMaker.build(id) local ok,e=EggCupMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(EggCupMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function EggCupMaker.getQualityBonus() local b=0; for _,bd in ipairs(EggCupMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function EggCupMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and EggCupMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and EggCupMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and EggCupMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and EggCupMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and EggCupMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and EggCupMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and EggCupMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and EggCupMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #EggCupMaker.buildings==0 then return false,"Potrebna skodelična delavnica" end; if not EggCupMaker.maker then return false,"Potreben skodeličar" end; return true end
function EggCupMaker.make(pt,qty) qty=qty or 1; local ok,e=EggCupMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then EggCupMaker.ironStock=EggCupMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then EggCupMaker.bronzeStock=EggCupMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then EggCupMaker.woodStock=EggCupMaker.woodStock-d.woodCost*qty end; if d.leatherCost then EggCupMaker.leatherStock=EggCupMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then EggCupMaker.silverStock=EggCupMaker.silverStock-d.silverCost*qty end; if d.goldCost then EggCupMaker.goldStock=EggCupMaker.goldStock-d.goldCost*qty end; if d.jewelCost then EggCupMaker.jewelStock=EggCupMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then EggCupMaker.pearlStock=EggCupMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if EggCupMaker.maker then t=math.max(1,t-math.floor(EggCupMaker.maker.skill/13)) end; table.insert(EggCupMaker.activeMaking,{id="eggcup_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function EggCupMaker.completeMaking(m) local q=1.0+(EggCupMaker.getQualityBonus()/100); if EggCupMaker.maker then q=q+(EggCupMaker.maker.skill/140) end; q=math.min(2.5,q); EggCupMaker.productStock[m.productType]=(EggCupMaker.productStock[m.productType] or 0)+m.quantity; EggCupMaker.totalProducts=EggCupMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if EggCupMaker.maker then EggCupMaker.maker.itemsMade=EggCupMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then EggCupMaker.maker.skill=math.min(100,EggCupMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skodelica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"eggcup.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function EggCupMaker.update(dt) if not _G.state then return end; EggCupMaker.dayTimer=EggCupMaker.dayTimer+dt; if EggCupMaker.dayTimer>=30 then EggCupMaker.dayTimer=0; for i=#EggCupMaker.activeMaking,1,-1 do local m=EggCupMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then EggCupMaker.completeMaking(m); table.remove(EggCupMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(EggCupMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if EggCupMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function EggCupMaker.getStats() return {ironStock=EggCupMaker.ironStock,bronzeStock=EggCupMaker.bronzeStock,woodStock=EggCupMaker.woodStock,leatherStock=EggCupMaker.leatherStock,silverStock=EggCupMaker.silverStock,goldStock=EggCupMaker.goldStock,jewelStock=EggCupMaker.jewelStock,pearlStock=EggCupMaker.pearlStock,productStock=EggCupMaker.productStock,numBuildings=#EggCupMaker.buildings,hasMaker=EggCupMaker.maker~=nil,makerName=EggCupMaker.maker and EggCupMaker.maker.name or "—",makerSkill=EggCupMaker.maker and EggCupMaker.maker.skill or 0,activeMaking=#EggCupMaker.activeMaking,totalProducts=EggCupMaker.totalProducts} end
return EggCupMaker
